n=16
out=[[7]*n for _ in range(n)]
segments={5:[(0,7,6),(4,7,6)], 8:[(4,11,6)], 4:[(6,13,6),(8,15,6)]}
# segment tuples (start row, start col, length); slope down-left
for color, items in segments.items():
    for r,c,L in items:
        for k in range(L):
            rr,cc=r+k,c-k
            assert 0<=rr<n and 0<=cc<n,(color,rr,cc)
            assert out[rr][cc]==7
            out[rr][cc]=color
[' '.join(map(str,row)) for row in out]

out=[[7]*16 for _ in range(16)]
segments={5:[(0,7,6),(2,9,6)],8:[(4,11,6)],4:[(6,13,6),(8,15,6)]}
for color,items in segments.items():
    for r,c,L in items:
        for k in range(L):
            assert 0<=r+k<16 and 0<=c-k<16
            assert out[r+k][c-k]==7
            out[r+k][c-k]=color
rows=[' '.join(map(str,row)) for row in out]
rows
